  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	    private static final int NEGATIVE_CYCLE_MARKER = -1;
  6	    private static final int FROM_INDEX = 0;
  7	    private static final int TO_INDEX = 1;
  8	    private static final int WEIGHT_INDEX = 2;
  9	    private static final int EDGE_FIELD_COUNT = 3;
 10	
 11	    private BellmanFord() {
 12	    }
 13	
 14	    static int[] bellmanFord(int vertexCount, int[][] edgeData, int source) {
 15	        Graph graph = Graph.from(vertexCount, edgeData);
 16	        graph.validateSource(source);
 17	        return shortestPathsFrom(graph, source);
 18	    }
 19	
 20	    private static int[] shortestPathsFrom(Graph graph, int source) {
 21	        int[] distances = initialDistances(graph.vertexCount, source);
 22	
 23	        for (int pass = 1; pass < graph.vertexCount; pass++) {
 24	            if (!graph.relaxEdges(distances)) {
 25	                break;
 26	            }
 27	        }
 28	
 29	        if (graph.hasReachableNegativeCycle(distances)) {
 30	            return negativeCycleResult();
 31	        }
 32	
 33	        return distances;
 34	    }
 35	
 36	    private static int[] initialDistances(int vertexCount, int source) {
 37	        int[] distances = new int[vertexCount];
 38	        Arrays.fill(distances, INF);
 39	        distances[source] = 0;
 40	        return distances;
 41	    }
 42	
 43	    private static int[] negativeCycleResult() {
 44	        return new int[]{NEGATIVE_CYCLE_MARKER};
 45	    }
 46	
 47	    private static String formatDistances(int[] distances) {
 48	        StringBuilder output = new StringBuilder();
 49	        for (int distance : distances) {
 50	            output.append(distance).append(' ');
 51	        }
 52	
 53	        return output.toString();
 54	    }
 55	
 56	    private static final class Edge {
 57	        private final int from;
 58	        private final int to;
 59	        private final int weight;
 60	
 61	        private Edge(int from, int to, int weight) {
 62	            this.from = from;
 63	            this.to = to;
 64	            this.weight = weight;
 65	        }
 66	
 67	        private boolean isWithin(int vertexCount) {
 68	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 69	        }
 70	
 71	        private boolean relax(int[] distances) {
 72	            if (!canRelax(distances)) {
 73	                return false;
 74	            }
 75	
 76	            distances[to] = distances[from] + weight;
 77	            return true;
 78	        }
 79	
 80	        private boolean canRelax(int[] distances) {
 81	            return distances[from] != INF && distances[from] + weight < distances[to];
 82	        }
 83	    }
 84	
 85	    private static final class Graph {
 86	        private final int vertexCount;
 87	        private final Edge[] edges;
 88	
 89	        private Graph(int vertexCount, Edge[] edges) {
 90	            this.vertexCount = vertexCount;
 91	            this.edges = edges;
 92	        }
 93	
 94	        private static Graph from(int vertexCount, int[][] edgeData) {
 95	            if (vertexCount < 0) {
 96	                throw new IllegalArgumentException("Vertex count cannot be negative");
 97	            }
 98	
 99	            if (edgeData == null) {
100	                throw new IllegalArgumentException("Edges cannot be null");
101	            }
102	
103	            Edge[] edges = new Edge[edgeData.length];
104	            for (int i = 0; i < edgeData.length; i++) {
105	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
106	            }
107	
108	            return new Graph(vertexCount, edges);
109	        }
110	
111	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
112	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
113	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
114	            }
115	
116	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
117	            if (!edge.isWithin(vertexCount)) {
118	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
119	            }
120	
121	            return edge;
122	        }
123	
124	        private void validateSource(int source) {
125	            if (source < 0 || source >= vertexCount) {
126	                throw new IllegalArgumentException("Source vertex is out of range");
127	            }
128	        }
129	
130	        private boolean relaxEdges(int[] distances) {
131	            boolean changed = false;
132	
133	            for (Edge edge : edges) {
134	                if (edge.relax(distances)) {
135	                    changed = true;
136	                }
137	            }
138	
139	            return changed;
140	        }
141	
142	        private boolean hasReachableNegativeCycle(int[] distances) {
143	            for (Edge edge : edges) {
144	                if (edge.canRelax(distances)) {
145	                    return true;
146	                }
147	            }
148	
149	            return false;
150	        }
151	    }
152	
153	    public static void main(String[] args) {
154	
155	        int vertexCount = 5;
156	
157	        int[][] edges = new int[][] {
158	            {1, 3, 2},
159	            {4, 3, -1},
160	            {2, 4, 1},
161	            {1, 2, 1},
162	            {0, 1, 5}
163	        };
164	
165	        int source = 0;
166	
167	        int[] distances = bellmanFord(vertexCount, edges, source);
168	
169	        System.out.print(formatDistances(distances));
170	    }
171	}

